from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
import itertools
from collections import Counter


def _route(data, minimum_duration, exact_coupons):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bits.get(start, 0)
    budget = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (start, initial_mask, 0)
    distances = {initial: data["start"]}
    queue = [(data["start"], start, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (used == budget if exact_coupons else True)):
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < budget:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            next_mask = mask | bits.get(edge["v"], 0)
            for duration, next_used in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_used))
    return {"arrival": None}


def _build_route(minimum_duration, exact_coupons):
    return lambda data: _route(data, minimum_duration, exact_coupons)


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, data["rounding"])
        tax = _round(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _active_dependencies(row, features):
    return [dep for dep in row.get("deps", [])
            if not dep.get("feature") or dep["feature"] in features]


def _resolve(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, []))
        choices.append([-1] + versions)
    best_vector = None
    best = None

    for vector in itertools.product(*choices):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        valid = True
        for name, bounds in data["roots"].items():
            version = installed.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        if any(name in installed and installed[name] != version
               for name, version in pins.items()):
            continue

        closure = set(data["roots"])
        pending = list(closure)
        graph = {}
        while pending and valid:
            name = pending.pop()
            version = installed.get(name)
            if version is None:
                valid = False
                break
            row = next((r for r in packages[name] if r["version"] == version), None)
            if row is None:
                valid = False
                break
            dependencies = _active_dependencies(row, features)
            graph[name] = []
            for dep in dependencies:
                child = dep["name"]
                child_version = installed.get(child)
                if child_version is None or not dep["min"] <= child_version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(child)
                if child not in closure:
                    closure.add(child)
                    pending.append(child)
        if not valid or set(installed) != closure:
            continue

        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(child) for child in graph.get(name, [])):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in closure):
            continue

        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = installed
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _feasible_subset(selected, data, jobs_by_id):
    ids = {job["id"] for job in selected}
    if not set(data.get("mandatory", [])).issubset(ids):
        return False
    counts = Counter(job["group"] for job in selected)
    for group, (low, high) in data.get("quotas", {}).items():
        count = counts.get(group, 0)
        if not low <= count <= high:
            return False

    active_ends = []
    for job in sorted(selected, key=lambda row: (row["start"], row["end"], row["id"])):
        while active_ends and active_ends[0] <= job["start"]:
            heapq.heappop(active_ends)
        heapq.heappush(active_ends, job["end"])
        if len(active_ends) > 2:
            return False
    return True


def _select_jobs(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for subset in itertools.combinations(jobs, k):
        if _feasible_subset(subset, data, {}):
            ids = sorted(job["id"] for job in subset)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _build_route(2, True),
    "component_02": _build_route(1, False),
    "component_03": _build_route(1, True),
    "component_04": _build_route(2, False),
    "component_05": _build_route(2, True),
    "component_06": _ledger,
    "component_07": _resolve,
    "component_08": _select_jobs,
}
